let () =
  Fmt.pr "%a" Vhs.pp
    [
      Vhs.comment
        "Generated by tape.ml: permanent history above bounded current \
         activity.";
      Vhs.require "dune";
      Vhs.output "examples/layout/layout.gif";
      Vhs.blank;
      Vhs.set (Shell "bash");
      Vhs.set (Font_size 18);
      Vhs.set (Width 1000);
      Vhs.set (Height 460);
      Vhs.set (Theme "Builtin Dark");
      Vhs.set (Padding 20);
      Vhs.set (Typing_speed (Ms 20));
      Vhs.blank;
      Vhs.type' "dune exec examples/layout/main.exe";
      Vhs.key Enter;
      (* VHS does not match the final line once the live rows have been
            redrawn, so wait out the six-second run instead. *)
      Vhs.sleep (Ms 10000);
    ]
